function Modules({go,notify,credentialIssued,setCredentialIssued}) {
  const [tab,setTab]=useState("architecture");
  const [issued,setIssued]=useState(false);
  const [notes,setNotes]=useState("");
  const moduleCards=[
    {title:"Enrolment Management",sub:"Approved intake vs. actual enrolment",desc:"Capacity, categories and exception workflows",icon:GraduationCap,tone:"blue",action:()=>go("students")},
    {title:"Document Management",sub:"Encrypted files · IPFS CID",desc:"Permissions, versions and secure download",icon:FileText,tone:"teal",action:()=>setTab("documents")},
    {title:"Blockchain Explorer",sub:"Local Hardhat development network",desc:"Commitments, events and transaction state",icon:Blocks,tone:"purple",action:()=>setTab("blockchain")},
    {title:"Audit Trail",sub:"Actor · action · timestamp · event hash",desc:"Search events and export compliance logs",icon:ClipboardList,tone:"amber",action:()=>setTab("audit")},
    {title:"User & Role Management",sub:"Role-based access with institution scope",desc:"Invites, wallet binding and account status",icon:UserRound,tone:"blue",action:()=>setTab("roles")},
    {title:"Consent Management",sub:"Student-controlled claim sharing",desc:"Expiry, revocation and sharing history",icon:ShieldCheck,tone:"teal",action:()=>go("wallet")}
  ];
  return <><PageHeader eyebrow="OPERATIONS / SECURITY ARCHITECTURE" title="Platform Modules" subtitle="Explore supporting workflows and the boundaries between application, services, data and trust layers." actions={<Button icon={Download} onClick={()=>notify("Architecture summary prepared")}>Export overview</Button>}/><div className="module-grid">{moduleCards.map(m=><button className="module-card card" key={m.title} onClick={m.action}><span className={`module-icon ${m.tone}`}><m.icon size={20}/></span><b>{m.title}</b><strong>{m.sub}</strong><small>{m.desc}</small><span className="module-link">Open module <ArrowUpRight size={14}/></span></button>)}</div>
    <section className="card architecture-card"><div className="section-heading"><div><h3>Logical technical architecture</h3><p>Separation of responsibilities and trust boundaries</p></div><span className="count-pill">4 layers</span></div><div className="architecture-layers">{[{name:"PRESENTATION",tone:"blue",items:[["React web app","Role-based responsive views"],["Dashboard & forms","Tables, reports, consent UI"]]},{name:"AUTHENTICATION & API",tone:"teal",items:[["Wallet signature","MetaMask-compatible flow"],["Application API","RBAC · institution scope"]]},{name:"DATA & DOCUMENTS",tone:"purple",items:[["PostgreSQL","Metadata & lifecycle state"],["Encrypted storage","AES-256-GCM · IPFS CID"]]},{name:"TRUST & VERIFICATION",tone:"amber",items:[["Verifiable credentials","W3C VC data model"],["Blockchain layer","Solidity · local Hardhat"]]}].map((l,i)=><div className={`architecture-layer ${l.tone}`} key={l.name}><div className="layer-label">{l.name}</div><div className="layer-items">{l.items.map(it=><div className="layer-item" key={it[0]}><b>{it[0]}</b><small>{it[1]}</small></div>)}</div>{i<3&&<div className="layer-connector"><span/><ChevronDown size={15}/><span/></div>}</div>)}</div><div className="architecture-note"><AlertTriangle size={15}/> Prototype note: wallet signing, cryptographic proof checks, IPFS storage and blockchain transactions are simulated. The UI does not claim to validate real credentials.</div></section>
    <section className="card module-detail"><div className="section-heading"><div><h3>Operational preview</h3><p>Simulated credential, storage, audit and access states</p></div><div className="tab-strip">{[["architecture","Architecture"],["documents","Documents"],["blockchain","Blockchain"],["audit","Audit trail"],["roles","Roles"]].map(t=><button className={tab===t[0]?"selected":""} onClick={()=>setTab(t[0])} key={t[0]}>{t[1]}</button>)}</div></div>
      {tab==="architecture"&&<div className="ops-grid"><OpsItem icon={Database} title="Metadata database" status="Connected" detail="PostgreSQL · student and credential references"/><OpsItem icon={LockKeyhole} title="Encryption service" status="Ready" detail="AES-256-GCM · keys are never shown"/><OpsItem icon={Fingerprint} title="Identity matching" status="Ready" detail="HMAC-based lookup token concept"/><OpsItem icon={Link2} title="Trust layer" status="Simulated" detail="Local blockchain and VC lifecycle"/></div>}
      {tab==="documents"&&<div className="table-wrap"><table><thead><tr><th>DOCUMENT</th><th>ENCRYPTION</th><th>STORAGE REFERENCE</th><th>ACCESS</th></tr></thead><tbody>{[["Interim_Transcript.pdf","AES-256-GCM","bafybei…demoCID","Restricted"],["Programme_Approval.pdf","AES-256-GCM","bafybe…sampleCID","Admin only"],["Student_Proof.json","AES-256-GCM","bafybei…proofCID","Consent required"]].map(r=><tr key={r[0]}>{r.map(v=><td key={v}>{v}</td>)}</tr>)}</tbody></table></div>}
      {tab==="blockchain"&&<div className="ops-grid"><OpsItem icon={Blocks} title="Network" status="Local demo" detail="Hardhat development network"/><OpsItem icon={Link2} title="Contract" status="Sample" detail="0x71C7…28B4"/><OpsItem icon={Activity} title="Latest block" status="#1842" detail="Illustrative block height"/><OpsItem icon={ShieldCheck} title="Credential anchor" status={credentialIssued?"Pending anchor":"Not anchored"} detail="No real on-chain transaction"/></div>}
      {tab==="audit"&&<div className="audit-list">{[["Today · 14:32","Institution Admin","Viewed student record STU-24081"],["Today · 13:57","Admission Officer","Imported enrolment batch CSV-882"],["Yesterday · 17:12","Regulatory Officer","Generated Q3 compliance report"],["Yesterday · 15:40","System","Duplicate case CASE-0257 resolved"]].map(r=><div className="audit-row" key={r[0]}><Clock3 size={16}/><span>{r[0]}</span><b>{r[1]}</b><small>{r[2]}</small></div>)}</div>}
      {tab==="roles"&&<div className="role-grid">{[["Institution Admin","Student records, credentials, local reports"],["AICTE Admin","Institution approvals, national compliance"],["Student","Wallet, credential view, consent control"],["Employer / Verifier","Request claims, verify with consent"],["Regulatory Officer","Analytics, compliance exports"],["Admission Officer","Enrolment and source validation"]].map(r=><div className="role-row" key={r[0]}><UserRound size={17}/><div><b>{r[0]}</b><small>{r[1]}</small></div><Status value="Role scoped"/></div>)}</div>}
    </section>
  </>;
}
function OpsItem({icon:Icon,title,status,detail}){return <div className="ops-item"><span><Icon size={18}/></span><div><b>{title}</b><small>{detail}</small></div><Status value={status}/></div>}

createRoot(document.getElementById("root")).render(<App/>);
